import { Tabs } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import {
  SETTINGS_LINKPREVIEW_MODAL,
  SETTINGS_LINKPREVIEW_TABS,
} from './../../plugin-link-preview/data-hooks.js';
import {
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { linkPreviewModals } from '../consts.js';
import classes from '../statics/styles/settings-modal-scss.js';
import { DesignTab } from './design-tab.js';
import { SettingsTab } from './settings-tab.js';

type SettingsModalProps = {
  nodeId: string;
  activeTab: 'settings' | 'design';
  config: $TSFixMe;
  referenceElement: HTMLElement | undefined;
};

export const SettingsModal: FC<SettingsModalProps> = ({
  nodeId,
  activeTab,
  config,
  referenceElement,
}) => {
  const modalService = useContext(ModalServiceContext) || {};
  const containerEl = usePanelContainerElement();
  const { t, isMobile } = useContext(RicosContext);
  const [activeId, setActiveId] = useState<'settings' | 'design'>(activeTab);
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.LINK_PREVIEW);
  const isColorPickerModalOpen = () => modalService.isModalOpen(linkPreviewModals.colorPicker);

  const closeModal = () => modalService.closeModal(linkPreviewModals.settings);

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;

      if (referenceElement?.contains(target as Node)) {
        return;
      }

      closeModal();
    },
    disable: isColorPickerModalOpen(),
  });

  if (!pmNodeAttrs) {
    logInvariant(new Error('Link preview settings: node attrs not found'));
    return null;
  }

  return (
    <div className={classes.modal}>
      <Panel
        closeButtonProps={{ onClick: () => modalService.closeModal(linkPreviewModals.settings) }}
        dataHook={SETTINGS_LINKPREVIEW_MODAL}
        maxHeight={isMobile ? undefined : 590}
      >
        <PanelHeader title={t('LinkPreview_Design_Panel_Header')} />

        <Tabs
          dataHook={SETTINGS_LINKPREVIEW_TABS}
          size="small"
          alignment="center"
          type="uniformFull"
          minWidth={0}
          activeId={activeId}
          onClick={value => setActiveId(value.id as 'settings' | 'design')}
          items={[
            { id: 'settings', title: t('LinkPreview_Design_Panel_Tab_Layout') },
            { id: 'design', title: t('LinkPreview_Design_Panel_Tab_Design') },
          ]}
        />
        {activeId === 'settings' && <SettingsTab nodeId={nodeId} />}
        {activeId === 'design' && (
          <DesignTab
            nodeId={nodeId}
            config={config}
            modalId={linkPreviewModals.settings}
            pmNodeAttrs={pmNodeAttrs}
            patchPmNodeAttrs={patchPmNodeAttrs}
          />
        )}
      </Panel>
    </div>
  );
};
