import { definePmNodeConverter } from './../pm-converters/types.js';
import type { Link, LinkPreviewData } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../_shared/link/link-converters.js';

export const linkPreviewConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.LINK_PREVIEW],
    convert: node => ({
      type: Node_Type.LINK_PREVIEW,
      attrs: {
        ...node.linkPreviewData,
        id: node.id,
      },
    }),
  },
  fromPm: {
    types: [Node_Type.LINK_PREVIEW],
    convert: node => {
      const { id, animation, ...data } = node.attrs || {};

      if (node?.attrs?.error || node?.attrs?.loading) {
        return undefined;
      }

      return {
        type: Node_Type.LINK_PREVIEW,
        id,
        nodes: [],
        linkPreviewData: {
          ...(data as LinkPreviewData),
          link: fromTiptapLinkConverter(data.link) as Link,
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
