export const startsWithHttps = (url: string) => /^https:/.test(url);

export const startsWithHttp = (url: string) => /^http:/.test(url);

export const getHost = (url?: string) =>
  !url
    ? url
    : !startsWithHttps(url) && !startsWithHttp(url)
      ? new URL(`http://${url}`).host
      : new URL(url).host;

export const getUrlForDisplay = (url: string) => url.replace(/^https?:\/\//, '');
