import React from 'react';

import type { EmbedNode } from './../../ricos-schema/next-schema/index.js';

import { HtmlViewer } from '../../plugin-html/viewer/html-viewer.js';
import type { LinkPreviewPluginEditorConfig } from '../types.js';

export const EmbedViewer: React.FC<{
  node: EmbedNode;
  settings: LinkPreviewPluginEditorConfig;
  iframeSandboxDomain: string;
}> = ({ node, settings, iframeSandboxDomain }) => {
  const htmlCompProps = {
    htmlData: {
      ...node.embedData,
      html: unescape(node.embedData.oembed?.html ?? ''),
    },
    settings,
    iframeSandboxDomain,
  };
  return <HtmlViewer {...htmlCompProps} />;
};
