import { TIPTAP_EMBED_TYPE, TIPTAP_LINK_PREVIEW_TYPE } from './../../ricos-content/index.js';
import { convertBlockDataToRicos } from './../../ricos-content/lib/convert-block-data-to-ricos.js';
import type { LinkPreviewData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  ExtensionProps,
  NodeConfig,
  RicosExtension,
  RicosExtensionConfig,
} from './../../ricos-types/index.js';
import type { DeepPartial } from './../../_shared/ts-utils/deep-partial.js';
import type { KeyboardShortcutCommand } from './../../tiptap/core/index.js';
import type { Attrs, Node, ResolvedPos } from './../../tiptap/pm/model.js';
import type { Editor } from './../../tiptap/react/index.js';
import {
  createRicosFunctionalExtension,
  createRicosNodeExtension,
} from './../../plugin-commons/index.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';

import {
  createLinkPreviewData,
  fetchLinkPreview,
  shouldAddEmbed,
  shouldAddLinkPreview,
} from '../lib/utils.js';
import type { LinkPreviewPluginEditorConfig } from '../types.js';
import { LINK_PREVIEW_TYPE } from '../types.js';
import { Embed } from './embed.js';
import { LinkPreview } from './link-preview.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    linkPreview: {
      /**
       * Set a linkPreview node
       */
      setLinkPreview: (attributes: DeepPartial<LinkPreviewData>) => ReturnType;
      /**
       * Create link preview
       */
      createLinkPreview: () => ReturnType;
      /**
       * Update Image's loading state
       */
      setLinkPreviewLoading: (isLoading: boolean) => ReturnType;
      /**
       * Update Image's loading state
       */
      setLinkPreviewError: (isError: boolean) => ReturnType;
    };
  }
}

//// Regexes should be shared with link extension

/**
 * A regex that matches any string that contains a link
 */
const urlRegex =
  // oxlint-disable-next-line max-len
  /(?:https?:\/\/)?(?:www\.)?[-a-zA-Z0-9@:%._+~#=]{1,256}\.[a-zA-Z]{2,}\b(?:[-a-zA-Z0-9@:%._+~#=?!&/]*)(?:[-a-zA-Z0-9@:%._+~#=?!&/]*)/gi;

/**
 * A regex that matches an url
 */
const urlRegexExact = new RegExp('^' + urlRegex.source + '$', 'gi');

const isLinkOnlyBlock = ({
  pos,
  fromShortcut,
}: {
  pos: ResolvedPos;
  fromShortcut: boolean;
}): boolean =>
  fromShortcut
    ? pos.parent.childCount === 1 && pos.nodeBefore?.text?.search(urlRegexExact) !== -1
    : pos.parent.text?.search(urlRegexExact) !== -1;

const getLinkDeletionRange = ({
  pos,
  fromShortcut,
}: {
  pos: ResolvedPos;
  fromShortcut: boolean;
}) => {
  const parentText = pos.parent.textContent;
  const match = parentText.match(urlRegexExact);
  if (match) {
    const startIndex = parentText.indexOf(match[0]);
    return {
      from: pos.start() + startIndex,
      to: pos.start() + startIndex + match[0].length,
    };
  }

  if (fromShortcut) {
    return {
      from: pos.pos - (pos.nodeBefore?.nodeSize || 0),
      to: pos.pos + (pos.nodeAfter?.nodeSize || 0),
    };
  }

  return { from: pos.start(), to: pos.end() };
};

const extractUrlFromNode = (node: Node): string | undefined => {
  const linkMark = node.marks.find(mark => mark.type.name === 'LINK');

  const rawUrl = linkMark?.attrs?.link?.url ?? linkMark?.attrs?.href;

  return rawUrl?.trim();
};

const addLinkPreview =
  (config: LinkPreviewPluginEditorConfig): KeyboardShortcutCommand =>
  // @ts-expect-error
  ({ editor, tr }) => {
    tr?.setMeta('preventDispatch', true);
    const pos = editor.state.selection.$anchor;
    const {
      enableEmbed = true,
      enableLinkPreview = true,
      fetchData,
      link: linkConfig,
      fromShortcut = true,
    } = config || {};

    if (
      pos.nodeBefore?.text &&
      isLinkOnlyBlock({ pos, fromShortcut }) &&
      fetchData &&
      (enableEmbed || enableLinkPreview)
    ) {
      let isPreviewAdded = false;
      const { target, rel } = linkConfig || {};
      const url = extractUrlFromNode(pos.nodeBefore);

      if (!url) {
        return false;
      }

      insertPreviewPlaceholder(editor, url, pos, fromShortcut);

      fetchLinkPreview(fetchData, url)
        .then(linkPreviewData => {
          const shouldEmbed = shouldAddEmbed(
            linkPreviewData.html,
            enableEmbed,
            linkPreviewData.fixedUrl
          );

          const shouldPreview = shouldAddLinkPreview(linkPreviewData.title, enableLinkPreview);

          if (!shouldEmbed && !shouldPreview) {
            return;
          }
          isPreviewAdded = true;

          return createLinkPreviewData({ url, target, rel }, linkPreviewData, config).then(
            linkPreviewComponentData => {
              const convertedLinkPreviewData = convertBlockDataToRicos(
                LINK_PREVIEW_TYPE,
                linkPreviewComponentData
              );
              const placeholder = findPlaceholderNode(editor, url);
              if (!placeholder) {
                return;
              }

              if (shouldEmbed) {
                replacePlaceholderWithEmbed(editor, placeholder, convertedLinkPreviewData);
              } else {
                updatePlaceholderAttributes(editor, placeholder.id, {
                  ...convertedLinkPreviewData,
                  loading: false,
                  error: false,
                });
              }
            }
          );
        })
        .catch(() => {
          const placeholder = findPlaceholderNode(editor, url);
          if (placeholder) {
            updatePlaceholderAttributes(editor, placeholder.id, {
              loading: false,
              error: true,
              link: { url },
            });
          }
        })
        .finally(() => {});

      return isPreviewAdded;
    }

    return false;
  };

const insertPreviewPlaceholder = (
  editor: Editor,
  url: string,
  pos: ResolvedPos,
  fromShortcut: boolean
) => {
  editor
    .chain()
    .focus()
    .deleteRange(getLinkDeletionRange({ pos, fromShortcut }))
    .insertContent([
      { type: TIPTAP_LINK_PREVIEW_TYPE, attrs: { link: { url }, loading: true, error: false } },
      { type: 'PARAGRAPH' },
    ])
    .run();
};

const findPlaceholderNode = (
  editor: Editor,
  url: string
): { id: string; pos: number; size: number } | null => {
  let placeholderNode = null;
  editor.state.doc.descendants((node, pos) => {
    if (
      node.type.name === TIPTAP_LINK_PREVIEW_TYPE &&
      node.attrs.link?.url === url &&
      node.attrs.loading === true
    ) {
      placeholderNode = { id: node.attrs.id, pos, size: node.nodeSize };
      return false;
    }
    return true;
  });
  return placeholderNode;
};

const replacePlaceholderWithEmbed = (
  editor: Editor,
  placeholder: { id: string; pos: number; size: number },
  embedAttrs: any
) => {
  editor.state.doc.descendants((node, pos) => {
    if (node.type.name === TIPTAP_LINK_PREVIEW_TYPE && node.attrs.id === placeholder.id) {
      editor.commands.deleteRange({ from: pos, to: pos + node.nodeSize });
      return false;
    }
    return true;
  });

  editor
    .chain()
    .focus()
    .insertContent([{ type: TIPTAP_EMBED_TYPE, attrs: embedAttrs }, { type: 'PARAGRAPH' }])
    .run();
};

const updatePlaceholderAttributes = (editor: Editor, nodeId: string, attrs: Attrs) => {
  editor.chain().setNodeAttrsById(nodeId, attrs).setMeta('addToHistory', false).run();
};

export const tiptapExtensions = [
  createRicosNodeExtension({
    name: TIPTAP_LINK_PREVIEW_TYPE,
    groups: [
      'draggable',
      'not-overtypable',
      { group: 'resizable', options: { expandToFullWidthOnOverdrag: true } },
    ],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component: LinkPreview,
    createExtensionConfig() {
      return {
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        name: this.name,
        addAttributes: () => ({
          containerData: null,
          link: null,
          title: null,
          thumbnailUrl: null,
          description: null,
          html: null,
          styles: null,
          loading: {
            default: false,
          },
          error: {
            default: false,
          },
        }),
        addCommands() {
          return {
            setLinkPreviewLoading:
              (loading: boolean) =>
              ({ commands }) => {
                return commands.setNode('linkPreview', { loading });
              },
            setLinkPreviewError:
              (error: boolean) =>
              ({ commands }) => {
                return commands.setNode('linkPreview', { error });
              },
            setLinkPreview:
              attributes =>
              ({ commands }) => {
                return commands.setNode('linkPreview', attributes);
              },
          };
        },
      };
    },
  }),
  createRicosNodeExtension({
    name: TIPTAP_EMBED_TYPE,
    groups: ['overlay', 'draggable', 'not-overtypable'],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component: Embed,
    createExtensionConfig() {
      return {
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        name: this.name,
        addAttributes: () => ({
          containerData: null,
          oembed: null,
          src: null,
        }),
      };
    },
  }),
  createRicosFunctionalExtension({
    type: 'extension',
    groups: ['shortcuts-enabled'],
    name: 'linkPreviewEnter',
    reconfigure: (
      config: RicosExtensionConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>,
      services: TiptapAdapterServices
    ) => ({
      ...config,
      addKeyboardShortcuts() {
        const enableEnterToConvertLinks = settings.enableEnterToConvertLinks ?? true;

        if (!enableEnterToConvertLinks) {
          return {};
        }

        const newLine = addLinkPreview(settings as unknown as LinkPreviewPluginEditorConfig);

        const tiptapKeyboardShortcuts = {
          Enter: newLine,
        };

        const newLineShortcuts: any = [];
        //@ts-ignore
        services.shortcuts.shortcuts.forEach(shortcut => {
          if (shortcut.shortcut.name === 'NewLine') {
            newLineShortcuts.push(shortcut);
          }
        });

        newLineShortcuts.forEach((newLineShortcut: $TSFixMe) => {
          const modifier = newLineShortcut.keys.macOs.modifiers[0];
          const key = newLineShortcut.keys.macOs.key;
          const shortcutKey = modifier ? `${modifier}-${key}` : key;
          tiptapKeyboardShortcuts[shortcutKey as keyof typeof tiptapKeyboardShortcuts] = newLine;
        });

        return {
          ...tiptapKeyboardShortcuts,
        };
      },
      addCommands() {
        const linkPreviewCommand = addLinkPreview({
          ...settings,
          fromShortcut: false,
        } as unknown as LinkPreviewPluginEditorConfig);

        return {
          createLinkPreview: () => linkPreviewCommand,
        };
      },
    }),
    createExtensionConfig() {
      return {
        name: this.name,
        priority: 101,
      };
    },
  }),
];
