import React from 'react';

import type { EmbedNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';

import { embedConverter } from '../embed-converter.js';
import type { LinkPreviewPluginEditorConfig } from '../types.js';
import { EmbedViewer } from '../viewer/embed-viewer.js';

export const Embed: React.FC<PluginProps> = ({ settings, node }) => {
  const ricosNode = React.useMemo(() => embedConverter.fromPm.convert(node.toJSON()), [node]);

  return (
    <EmbedViewer
      node={ricosNode as EmbedNode}
      settings={settings as LinkPreviewPluginEditorConfig}
      iframeSandboxDomain={''}
    />
  );
};
