import {
  Instagram,
  InstagramSmall,
  TikTok,
  TikTokSmall,
  XCorp,
  XCorpSmall,
} from '@wix/wix-ui-icons-common/lazy';

import type { ModalService } from './../ricos-modals/modal-service.js';
import type { EditorPluginCreator, QuickAction } from './../ricos-types/index.js';
import {
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { posToDOMRect } from './../tiptap/index.js';
import type { Editor } from './../tiptap/core/index.js';

import { LinkPreviewProviders, socialModals } from './consts.js';
import { DEFAULTS } from './defaults.js';
import { embedConverter } from './embed-converter.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { linkPreviewConverter } from './link-preview-converter.js';
import type { InsertModalProps } from './modals/insert-modal.js';
import { InsertModal } from './modals/insert-modal.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { LinkPreviewPluginEditorConfig } from './types.js';
import { LINK_PREVIEW_TYPE } from './types.js';

export const pluginLinkPreview: EditorPluginCreator<LinkPreviewPluginEditorConfig> = config => {
  const pluginConfig: LinkPreviewPluginEditorConfig = {
    type: 'linkPreview' as const,
    ...DEFAULTS.config,
    ...config,
  };
  return {
    config: pluginConfig,
    type: LINK_PREVIEW_TYPE,
    pmMarkConverters: [],
    pmNodeConverters: [linkPreviewConverter, embedConverter],
    tiptapExtensions,
    getAddButtons: (config, services) => getAddButtons(config, services),
    toolbar: {
      names: [RicosPluginToolbarNames.LINK_PREVIEW, RicosPluginToolbarNames.EMBED],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getQuickActions: ({ config, pluginServices }) => {
      const {
        fetchData,
        exposeEmbedButtons = [
          LinkPreviewProviders.Instagram,
          LinkPreviewProviders.TikTok,
          LinkPreviewProviders.Twitter,
        ],
      } = config || {};
      const isMobile = pluginServices.context.isMobile;

      const toggleInsertModal = ({
        id,
        socialType,
        modalService,
        editor,
      }: {
        id: string;
        socialType: InsertModalProps['socialType'];
        modalService: ModalService;
        editor: Editor;
      }) => {
        modalService.togglePluginPanel({
          id,
          Component: InsertModal,
          componentProps: {
            fetchData,
            socialType,
          },
          isMobile,
          positioning: {
            referenceElement: {
              getBoundingClientRect: () =>
                posToDOMRect(
                  editor.view,
                  editor.view.state.selection.from,
                  editor.view.state.selection.to
                ),
            },
            placement: isMobile ? 'bottom' : 'bottom-start',
          },
          mobileLayout: 'drawer',
        });
      };

      const actions: QuickAction[] = [];

      if (exposeEmbedButtons.includes(LinkPreviewProviders.Instagram)) {
        actions.push({
          id: `${Node_Type.LINK_PREVIEW}.instagram`,
          title: 'QuickActionsPlugin_ActionTitle_InstagramPost',
          icon: isMobile ? Instagram : InstagramSmall,
          section: quickActionsModalSections.Embed,
          tags: ['post', 'photo', 'video', 'social media', 'story', 'ig post', 'instagram'],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: socialModals.instagram,
              socialType: 'Instagram',
              modalService,
              editor,
            });
          },
        });
      }

      if (exposeEmbedButtons.includes(LinkPreviewProviders.TikTok)) {
        actions.push({
          id: `${Node_Type.LINK_PREVIEW}.tiktok`,
          title: 'QuickActionsPlugin_ActionTitle_TikTokVideo',
          icon: isMobile ? TikTok : TikTokSmall,
          section: quickActionsModalSections.Embed,
          tags: ['video', 'social media', 'content', 'short video', 'clip', 'tiktok'],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: socialModals.tiktok,
              socialType: 'TikTok',
              modalService,
              editor,
            });
          },
        });
      }

      if (exposeEmbedButtons.includes(LinkPreviewProviders.Twitter)) {
        actions.push({
          id: `${Node_Type.LINK_PREVIEW}.twitter`,
          title: 'QuickActionsPlugin_ActionTitle_XPost',
          icon: isMobile ? XCorp : XCorpSmall,
          section: quickActionsModalSections.Embed,
          tags: [
            'social media',
            'tweet',
            'update',
            'content',
            'post',
            'link',
            'article',
            'blog',
            'twitter',
            'x',
          ],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: socialModals.twitter,
              socialType: 'Twitter',
              modalService,
              editor,
            });
          },
        });
      }

      return actions;
    },
  };
};
