import { Unlink } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const UnlinkButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext) || {};

  return (
    <ToolbarButton
      prefix={Unlink}
      onClick={() => toolbarItem.commands?.click()}
      dataHook={dataHook}
      tooltip={t('LinkPreview_Unlink_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
