import { Box } from '@wix/design-system';
import React, { useContext, useMemo, useState } from 'react';

import { LINK_PREVIEW_TYPE } from './../../ricos-content/consts.js';
import { EditorContext, RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import type { LinkPreviewData, Link_Rel } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Link_Target } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { AttributesDesktop } from './../../_shared/link-modal/open-link-modal/attributes/attributes-desktop.js';

type Props = {
  nodeId: string;
};

export const SettingsTab = ({ nodeId }: Props) => {
  const { getPublicCommands } = useContext(EditorContext);
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);

  const initialData = useMemo(
    () => getPublicCommands().getBlockComponentData(nodeId) as LinkPreviewData,
    []
  );
  const [componentData, setComponentData] = useState<LinkPreviewData>(initialData);

  const tooltipProps = useMemo(
    () => ({
      appendTo: containerRef || undefined,
      fixed: true,
      zIndex: zIndexService.getZIndex('TOOLTIP'),
    }),
    [containerRef, zIndexService]
  );

  const handleOnChange = (data: LinkPreviewData) => {
    getPublicCommands().setBlock(nodeId, LINK_PREVIEW_TYPE, {
      ...componentData,
      ...data,
    });
  };

  const onChangeAttributes = (rel: Link_Rel | undefined, target: Link_Target) => {
    if (componentData.link) {
      const newData = {
        ...componentData,
        link: {
          ...componentData.link,
          target,
          rel,
        },
      };

      setComponentData(newData);
      handleOnChange(newData);
    }
  };

  return componentData?.link ? (
    <Box direction="vertical" padding="SP3" overflow="auto" ref={setContainerRef}>
      <AttributesDesktop
        link={{
          url: componentData.link.url || '',
          target: componentData.link.target || Link_Target.BLANK,
          rel: componentData.link.rel,
          anchor: componentData.link.anchor,
        }}
        onChange={onChangeAttributes}
        t={t}
        tooltipProps={tooltipProps}
      />
    </Box>
  ) : null;
};
