import { Button, Loader, MediaOverlay, Text } from '@wix/design-system';
import { Link, StatusAlertFilled } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/ricos-context.js';
import type { LinkPreviewNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import { getHost, getUrlForDisplay } from './../../plugin-link-preview/viewer/utils.js';

import { linkPreviewConverter } from '../link-preview-converter.js';
import classes from '../statics/styles/link-preview-scss.js';
import { LinkPreviewViewer } from '../viewer/link-preview-viewer.js';

export const LinkPreview: React.FC<PluginProps> = ({ node, editor }) => {
  const ricosNode = React.useMemo(() => linkPreviewConverter.fromPm.convert(node.toJSON()), [node]);

  const { loading, error, link } = node.attrs;

  return (
    <>
      {loading && <LinkPreviewLoading />}
      {error && <LinkPreviewError editor={editor} link={link} />}
      {!loading && !error && <LinkPreviewViewer node={ricosNode as LinkPreviewNode} />}
    </>
  );
};

const LinkPreviewLoading = () => {
  const linkPreviewStyles = classes;
  const { loadingContainer } = linkPreviewStyles;

  return (
    <div className={loadingContainer}>
      <Loader size="small" />
    </div>
  );
};

const LinkPreviewError = ({ editor, link }: { editor: Editor; link: any }) => {
  const { t } = useContext(RicosContext);

  const showAsALink = () => {
    const url = link?.url;

    if (!url) {
      return;
    }

    const { state } = editor;
    const { selection } = state;
    const from = selection.from;

    editor
      .chain()
      .focus()
      .setMeta('allowTextReplace', true)
      .insertContent(url + ' ')
      .setTextSelection({ from, to: from + url.length + 1 })
      .run();
  };

  return (
    <MediaOverlay
      skin="dark"
      media={
        <div className={classes.linkPreviewContainer}>
          <figure className={classes.linkPreview}>
            <div className={classes.linkPreviewPlaceholder} />
            <section className={classes.linkPreviewInfo}>
              <div className={classes.linkPreviewUrl}>
                {getUrlForDisplay(getHost(link?.url) || link?.url || '')}
              </div>
            </section>
          </figure>
        </div>
      }
    >
      <MediaOverlay.Content visible="always">
        <div className={classes.overlay}>
          <div className={classes.errorContainer}>
            <div className={classes.errorInfo}>
              <div className={classes.errorIcon}>
                <StatusAlertFilled color="white" />
              </div>
              <div>
                <Text light weight="bold">
                  {t('LinkPreview_Error_Title')}
                </Text>
                <br />
                <Text light>{t('LinkPreview_Error_Subtitle')}</Text>
              </div>
            </div>
            <Button prefixIcon={<Link />} priority="secondary" onClick={showAsALink}>
              {t('LinkPreview_Error_Button')}
            </Button>
          </div>
        </div>
      </MediaOverlay.Content>
    </MediaOverlay>
  );
};
