import { definePmNodeConverter } from './../pm-converters/types.js';
import type { EmbedData } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

export const embedConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.EMBED],
    convert: node => ({
      type: Node_Type.EMBED,
      attrs: {
        ...node.embedData,
        id: node.id,
      },
    }),
  },
  fromPm: {
    types: [Node_Type.EMBED],
    convert: node => {
      const { id, animation, ...data } = node.attrs || {};
      return {
        type: Node_Type.EMBED,
        id,
        nodes: [],
        embedData: {
          ...(data as EmbedData),
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
