import React from 'react';

import type { LinkPreviewNode } from './../../ricos-schema/next-schema/index.js';
import type { Helpers, LinkPreviewData } from './../../ricos-types/index.js';
import { Node_Type } from './../../ricos-types/index.js';
import { resolveDocumentColorToCss } from './../../_shared/theme-color-token.js';
import { Image } from './../../ui-components/Components/image.js';

import { LINK_PREVIEW_VIEWER } from '../data-hooks.js';
import classes from '../statics/styles/link-preview-scss.js';
import { LINK_PREVIEW_TYPE } from '../types.js';
import { getHost, getUrlForDisplay } from './utils.js';

export const LinkPreviewViewer: React.FC<{
  node: LinkPreviewNode;
  helpers?: Helpers;
}> = ({ node, helpers }) => {
  const onLinkPreviewClick = () => {
    if (node.type === 'LINK_PREVIEW') {
      helpers?.onViewerAction?.(
        LINK_PREVIEW_TYPE,
        'Click',
        node.linkPreviewData.link?.url || '',
        node.id,
        {
          type: Node_Type.LINK_PREVIEW,
          linkPreviewData: node.linkPreviewData as LinkPreviewData,
        }
      );
    }
  };

  const { title = '', description, thumbnailUrl, link, styles } = node.linkPreviewData;

  return (
    <div
      className={classes.linkPreviewContainer}
      data-hook={LINK_PREVIEW_VIEWER}
      style={
        {
          '--link-preview-border-width':
            styles?.borderWidth !== undefined ? `${styles.borderWidth}px` : undefined,
          '--link-preview-border-color': resolveDocumentColorToCss(styles?.borderColor),
          '--link-preview-bg-color': resolveDocumentColorToCss(styles?.backgroundColor),
          '--link-preview-border-radius':
            styles?.borderRadius !== undefined ? `${styles.borderRadius}px` : undefined,
          '--link-preview-link-color': resolveDocumentColorToCss(styles?.linkColor),
          '--link-preview-title-color': resolveDocumentColorToCss(styles?.titleColor),
          '--link-preview-subtitle-color': resolveDocumentColorToCss(styles?.subtitleColor),
        } as React.CSSProperties
      }
    >
      {/* oxlint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions */}
      <figure
        className={`${classes.linkPreview} ${
          styles?.thumbnailPosition === 'END'
            ? classes.thumbnailEnd
            : styles?.thumbnailPosition === 'START'
              ? classes.thumbnailStart
              : styles?.thumbnailPosition === 'TOP'
                ? classes.thumbnailTop
                : ''
        }`}
        onClick={onLinkPreviewClick}
        style={{
          height: 'auto',
          alignItems: styles?.thumbnailPosition === 'TOP' ? 'center' : undefined,
        }}
      >
        {thumbnailUrl && styles?.thumbnailPosition !== 'HIDDEN' && (
          <Image
            containerProps={{
              className:
                styles?.thumbnailPosition === 'TOP'
                  ? classes.linkPreviewResponsiveImage
                  : classes.linkPreviewImage,
            }}
            uri={thumbnailUrl}
            width={400}
            height={200}
            displayMode="fill"
            alt={title}
          />
        )}
        <section className={classes.linkPreviewInfo}>
          <div className={classes.linkPreviewUrl} dir="auto">
            {getUrlForDisplay(getHost(link?.url) || link?.url || '')}
          </div>
          <figcaption className={classes.linkPreviewTitle} dir="auto">
            {title}
          </figcaption>
          {description && (
            <div className={classes.linkPreviewDescription} dir="auto">
              {description}
            </div>
          )}
        </section>
      </figure>
    </div>
  );
};
